import sys,urllib.request,urllib.parse,urllib.error,json,gzip,time,concurrent.futures,threading,datetime
from pathlib import Path
from quiz_probe import payload
R=Path('live_audit/data/quiz_cases');R.mkdir(parents=True,exist_ok=True);O=Path('live_audit/results');stop=threading.Event()
ref=json.loads(Path('handoff_audit/new/KCODE_Developer_R479/tests/ui_results_728.json').read_text());started=datetime.datetime.now(datetime.timezone.utc).isoformat()
def run(item):
 key,expected=item;p,s,skin,sens=key.split('|');f=payload(p,None if s=='none'else s,skin,sens=='yes');out={'key':key,'request':f};dest=R/(key.replace('|','__')+'.json.gz')
 if stop.is_set():return dict(out,skipped='rate limit or forbidden')
 t=time.monotonic()
 try:
  req=urllib.request.Request('https://kcodeskin.com/api/quiz/submit-answers',data=urllib.parse.urlencode(f).encode(),headers={'Content-Type':'application/x-www-form-urlencoded','Accept':'application/json','Accept-Language':'ar'},method='POST')
  res=urllib.request.urlopen(req,timeout=45);raw=res.read();dest.write_bytes(gzip.compress(raw));data=json.loads(raw);d=data.get('data',{});out.update(status=res.status,elapsed=round(time.monotonic()-t,2),success=data.get('status'),actual_key=d.get('scenario_key'),rules_version=d.get('rules_version'),selection_complete=d.get('selection_complete'),missing_roles=d.get('missing_roles'),diagnosis=d.get('diagnosis'))
  for field in ['primary_routine','routine_support']:
   act=[x.get('sku')or x.get('product',{}).get('sku')for x in d.get(field,[])];exp=[ref['products'][i]['sku']for i in expected[field]];out[field]={'expected':exp,'actual':act,'set_match':set(act)==set(exp),'order_match':act==exp,'duplicates':len(act)!=len(set(act))}
  out['matches']=all(out[x]['set_match']for x in ['primary_routine','routine_support']);out['key_match']=d.get('scenario_key')==key
 except urllib.error.HTTPError as e:
  out['error']=str(e);out['http_status']=e.code
  if e.code in [403,429]:stop.set()
 except Exception as e:out['error']=type(e).__name__+': '+str(e)
 return out
rows=[]
with concurrent.futures.ThreadPoolExecutor(max_workers=3)as pool:
 for x in pool.map(run,ref['paths'].items()):
  rows.append(x)
  if len(rows)%32==0:
   (O/'quiz_progress.json').write_text(json.dumps({'started':started,'count':len(rows),'rows':rows},ensure_ascii=False));print('done',len(rows),'match',sum(z.get('matches',False)for z in rows),'errors',sum('error'in z for z in rows),flush=True)
report={'started':started,'completed':datetime.datetime.now(datetime.timezone.utc).isoformat(),'count':len(rows),'matches':sum(x.get('matches',False)for x in rows),'key_matches':sum(x.get('key_match',False)for x in rows),'errors':[x for x in rows if 'error'in x or 'skipped'in x],'rows':rows,'scope':'Live public recommendation endpoint, exact form generated by current browser code; not 728 separate UI journeys'}
(O/'quiz_all_728.json').write_text(json.dumps(report,ensure_ascii=False,indent=2));print('FINAL',json.dumps({k:v for k,v in report.items()if k!='rows'},ensure_ascii=False),flush=True)
